def arcs(x, y, r, n=6, op=.35, cor=BR):
    return ''.join(f'<div class="arcs" style="left:{x-r+i*r*.12}px;top:{y-r+i*r*.12}px;width:{2*(r-i*r*.12)}px;height:{r-i*r*.12}px;border-color:{cor};opacity:{op*(1-i/n/1.4)}"></div>' for i in range(n))

class Doc:
    def __init__(s, nome): s.nome = nome; s.p = []
    def page(s, body, sec='', lt=False, hf=True):
        n = len(s.p) + 1
        hdr = f'<div class="hd mono"><span>Al Kántara Group · {s.nome}</span><span>{sec}</span></div><div class="ft mono"><span>v1.0 · 2026</span><span>{n:02d}</span></div>' if hf else ''
        s.p.append(f'<section class="pg {"lt" if lt else ""}">{body}{hdr}</section>')
    def divider(s, num, titulo, sub, foto=None):
        bg = f'<div class="ph" style="position:absolute;inset:0;background-image:linear-gradient(90deg,{OB} 30%,rgba(10,12,16,.2)),url({U(foto)})"></div>' if foto else arcs(1500, 900, 620, 8, .3)
        s.page(f'{bg}<div style="position:absolute;left:96px;bottom:150px"><div class="mono br">Seção {num}</div><div class="ser" style="font-size:300px;line-height:.85;margin-top:20px">{titulo}</div><div class="p" style="max-width:720px;margin-top:30px">{sub}</div></div><div class="ser br" style="position:absolute;right:96px;top:120px;font-size:200px;opacity:.9">{num}</div>', titulo)
    def html(s): return f'<html><head><meta charset="utf-8"><style>{CSS}</style></head><body>{"".join(s.p)}</body></html>'

def two(lbl, titulo, txt, right, lt=False, sec=''):
    return (f'<div style="position:absolute;left:96px;top:150px;width:560px"><div class="mono br">{lbl}</div><div class="t2" style="margin:24px 0 32px">{titulo}</div><div class="p">{txt}</div></div>'
            f'<div style="position:absolute;left:760px;right:96px;top:150px;bottom:130px">{right}</div>')

def box(content, bg=OB, pad=60, extra=''):
    return f'<div style="background:{bg};width:100%;height:100%;display:grid;place-items:center;padding:{pad}px;{extra}">{content}</div>'

