def rgbc(h): h = h.lstrip('#'); return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))
def cmyk(h):
    r, g, b = [x/255 for x in rgbc(h)]; k = 1-max(r, g, b)
    return (0, 0, 0, 100) if k >= 1 else tuple(round(v*100) for v in ((1-r-k)/(1-k), (1-g-k)/(1-k), (1-b-k)/(1-k), k))
