def icon(k, c=MA, s=64): return f'<svg viewBox="0 0 48 48" width="{s}" height="{s}" fill="none" stroke="{c}" stroke-width="2" stroke-linecap="square">{ic[k]}</svg>'
M.page(two('3.5 · Iconografia', 'Linha de 2, canto reto.', 'Ícones lineares em grade de 48 px, traço de 2 px, terminações retas, sem preenchimento. A mesma geometria do símbolo: arcos perfeitos e linhas retas. Nunca misture com ícones de outros estilos.',
       '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;height:100%">' + ''.join(f'<div class="card" style="display:grid;place-items:center;align-content:center;gap:18px">{icon(k, BR if i % 5 == 0 else MA, 72)}<div class="mono" style="font-size:11px;opacity:.6">{k}</div></div>' for i, k in enumerate(ic)) + '</div>'), '03 · Ícones')
M.divider('04', 'Imagem', 'Fotografia de estrutura, luz rasante e pessoas trabalhando de verdade.', 'hero2.jpg')
M.page(two('4.1 · Direção de fotografia', 'Estrutura, luz e gente real.', '<b>Sim:</b> arquitetura e engenharia (pontes, concreto, vidro), luz rasante de fim de tarde, equipe real no trabalho, telas reais dos nossos produtos, São Luís como origem.<br><b>Tratamento:</b> duotom Obsidiana → Marfim quente, contraste alto, grão leve. Todas as fotos com o mesmo tratamento.<br><b>Não:</b> banco de imagem com aperto de mãos, robôs, cérebros brilhando, hologramas azuis, gente apontando para tela.',
       f'<div style="display:grid;grid-template-columns:2fr 1fr;grid-template-rows:1fr 1fr;gap:16px;height:100%"><div class="ph" style="grid-row:1/3;background-image:url({U("hero.jpg")})"></div><div class="ph" style="background-image:url({U("hero2.jpg")})"></div><div class="ph" style="background-image:url({U("slz2.jpg")})"></div></div>'), '04 · Fotografia')
M.page(two('4.2 · Motion', 'Devagar, como engenharia.', '<b>Abertura de marca:</b> os arcos se desenham de fora para dentro (600 ms cada, curva ease-out cúbica), o tabuleiro corre da esquerda, a luz bronze nasce por último como um sol.<br><b>Transições:</b> máscara em arco, cortes secos, nada de pulos ou elástico.<br><b>Texto:</b> sobe 24 px com fade, palavra por palavra.<br><b>Ritmo:</b> 24 fps, trilha grave e espaçada.',
       '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;height:100%">' + ''.join(f'<div class="card" style="position:relative;display:flex;flex-direction:column"><div style="flex:1;display:grid;place-items:center;padding:30px"><svg viewBox="0 0 240 200" width="100%"><path d="M20,150 A100,100 0 0 1 220,150" stroke="{MA}" stroke-width="13" fill="none" stroke-dasharray="315" stroke-dashoffset="{315*(1-min(1,f*1.6))}"/><path d="M54,150 A66,66 0 0 1 186,150" stroke="{MA}" stroke-width="13" fill="none" stroke-dasharray="208" stroke-dashoffset="{208*(1-max(0,min(1,f*1.6-.3)))}"/><rect x="2" y="160" width="{236*max(0,min(1,f*2-.8))}" height="7" fill="{MA}"/><path d="M88,150 A32,32 0 0 1 152,150 Z" fill="{BR}" opacity="{max(0,f*3-2)}"/></svg></div><div class="mono" style="padding:16px;font-size:12px;opacity:.7">{int(f*2400)} ms</div></div>' for f in (.25, .5, .75, 1)) + '</div>'), '04 · Motion')

