# ------------------------------------------------------------------ templates de post e slide
T = Doc('Templates')
for i in range(4): T.p.append(f'<section style="width:1080px;height:1350px;position:relative;overflow:hidden;font-family:Inter Tight;color:{MA};background:{OB};page-break-after:always" class="grain">{post(i, 2.25)}</section>')

def render():
    with sync_playwright() as p:
        b = p.chromium.launch(proxy={'server': os.environ['HTTPS_PROXY']} if os.environ.get('HTTPS_PROXY') else None, args=['--allow-file-access-from-files'])
        for doc, nome in [(M, 'alkantara-manual-de-marca'), (K, 'alkantara-branding-book')]:
            h = f'{G}/{nome}.html'; open(h, 'w').write(doc.html())
            pg = b.new_page(viewport={'width': 1920, 'height': 1080}); pg.goto('file://' + h); pg.wait_for_timeout(2500)
            pg.pdf(path=f'{OUT}/{nome}.pdf', width='1920px', height='1080px', print_background=True)
            os.makedirs(f'{OUT}/paginas/{nome}', exist_ok=True)
            for i, el in enumerate(pg.query_selector_all('section.pg')):
                el.screenshot(path=f'{OUT}/paginas/{nome}/{i+1:02d}.jpg', quality=82)
            print(nome, len(doc.p), 'páginas')
        h = f'{G}/templates.html'; open(h, 'w').write(f'<html><head><meta charset="utf-8"><style>{CSS}</style></head><body>{"".join(T.p)}</body></html>')
        pg = b.new_page(viewport={'width': 1080, 'height': 1350}); pg.goto('file://' + h); pg.wait_for_timeout(2000)
        os.makedirs(f'{OUT}/templates', exist_ok=True)
        for i, el in enumerate(pg.query_selector_all('section')): el.screenshot(path=f'{OUT}/templates/post-{i+1:02d}.png')
        b.close()
render()
